        check_output(1'b1);

        // Verify state persistence and edge transitions again
        // In B (out=1), in=1 -> B (out=1)
        in = 1'b1;
        check_output(1'b1);

        // In B (out=1), in=0 -> A (out=0)
        in = 1'b0;
        check_output(1'b0);

        // Test mid-sequence synchronous reset assertion
        reset = 1;
        in = 1'b1; // even with in=1, reset should force state B (out=1)
        @(posedge clk);
        #1;
        if (out !== 1'b1) begin
            $display("Time %0t: Synchronous reset during operation failed! Expected out=1, got %b", $time, out);
            errors = errors + 1;
        end

        reset = 0;
        check_output(1'b1); // in state B, in=1 keeps us in B (out=1)

